&lt;?php
session_start();
$DATABASE_HOST = 'localhost';
$DATABASE_USER = 'root';
$DATABASE_PASS = '';
$DATABASE_NAME = 'name';
$conn = mysqli_connect($DATABASE_HOST, $DATABASE_USER, $DATABASE_PASS, $DATABASE_NAME);
if ( mysqli_connect_errno() ) {
    exit('Failed to connect to MySQL: ' . mysqli_connect_error());
}
if ( !isset($_POST['username'], $_POST['password']) ) {
    exit('Please fill both the username and password fields!');
}
if ($stmt = $conn-&gt;prepare('SELECT id, password FROM accounts WHERE username = ?')){
$stmt-&gt;bind_param('s', $_POST['username']);
$stmt-&gt;execute();
$stmt-&gt;store_result();
}
if ($stmt-&gt;num_rows &gt; 0) {
    $stmt-&gt;bind_result($id, $password);
    $stmt-&gt;fetch();
    if (password_verify($_POST['password'], $password)) {
        session_regenerate_id();
        $_SESSION['loggedin'] = TRUE;
        $_SESSION['name'] = $_POST['username'];
        $_SESSION['id'] = $id;
        header('Location: home.php');
    } else {
        echo 'Incorrect password!.';
    }
} else {
    echo 'Incorrect username and/or password!';
}

$stmt-&gt;close();
?&gt;
</code></pre>

Q: Swagger UI not getting generated for serverless Express api A: <p>After debugging this for a long time, the issue turned out to be that <strong>Swagger UI static assets were not being served correctly in a serverless environment (Api call to asset files returns 404)</strong>.</p>
<p>The key here is to create <strong>three different routes</strong> for swagger as shown below instead of merging into one and serving the asset files from CDN instead of lambda:</p>
<ol>
<li><p>Serve <strong>three</strong> Swagger routes <strong>before any other routes</strong></p>
</li>
<li><p>Load Swagger UI CSS/JS from CDN (instead of local <code>swagger-ui-dist</code>)</p>
</li>
<li><p>Expose the OpenAPI JSON at <code>/docs.json</code></p>
</li>
</ol>
<p>This works with:<br />
<code>express</code><br />
<code>serverless-http</code><br />
<code>swagger-ui-express</code><br />
<code>@asteasolutions/zod-to-openapi</code></p>
<p>In main file (e.g. <code>main.js</code> / <code>app.js</code>), add these <strong>before any other routes</strong>:</p>
<pre><code>  app.get(&quot;/docs.json&quot;, swaggerJsonHandler);
  app.use(&quot;/docs&quot;, swaggerMiddleware);
  app.get(&quot;/docs&quot;, swaggerUiMiddleware);
</code></pre>
<p>then in swagger.js add above three route handler functions</p>
<pre class="lang-js prettyprint-override"><code>const CSS_URL =
  &quot;https://cdnjs.cloudflare.com/ajax/libs/swagger-ui/4.15.5/swagger-ui.min.css&quot;;
const JS_URLS = [
  &quot;https://cdnjs.cloudflare.com/ajax/libs/swagger-ui/4.15.5/swagger-ui-bundle.js&quot;,
  &quot;https://cdnjs.cloudflare.com/ajax/libs/swagger-ui/4.15.5/swagger-ui-standalone-preset.js&quot;,
];

const swaggerSpec = generateOpenAPIDocument();

export const swaggerMiddleware = swaggerUi.serve;

export const swaggerUiMiddleware = (req: Request, res: Response) =&gt; res.send( swaggerUi.generateHTML(swaggerSpec, {
  customCss: &quot;.swagger-ui .topbar { display: none }&quot;,
  customSiteTitle: &quot;Design Tool Backend API Documentation&quot;,
  customCssUrl: CSS_URL,
  customJs: JS_URLS,
    swaggerOptions: {
      url: &quot;./docs.json&quot;,
    },
}));

export const swaggerJsonHandler = (req: Request, res: Response) =&gt; {
  res.setHeader(&quot;Content-Type&quot;, &quot;application/json&quot;);
  res.send(swaggerSpec);
};
</code></pre>
<p>finally the function generateOpenAPIDocument.</p>
<pre class="lang-js prettyprint-override"><code>export function generateOpenAPIDocument() {
  const config = {
    openapi: '3.0.0',
    info: {
      title: 'Design Tool Backend API',
      version: '1.0.0',
      description: 'Express API documentation for the Design Tool Backend application',
      contact: {
        name: 'API Support',
        email: 'support@designtool.com',
      },
    },
    servers: [
      {
        url: '/Prod',
        description: 'Development server',
      },
    ],
  };

  return new OpenApiGeneratorV3(registry.definitions).generateDocument(config);
}
</code></pre>
